buggy.matrix_rank_rtol_outcomes:
import numpy as np

x = np.zeros((4, 3, 2))

def rank_len(rtol):
    try:
        res = np.linalg.matrix_rank(x, rtol=rtol)
        return float(res.shape[0])
    except ValueError:
        return float("nan")

probe("x=np.zeros((4,3,2)); matrix_rank(x, rtol=0.0)", rank_len(0.0))
probe("x=np.zeros((4,3,2)); matrix_rank(x, rtol=[0.0]*4)", rank_len([0.0] * 4))
probe("x=np.zeros((4,3,2)); matrix_rank(x, rtol=np.zeros((4,)))", rank_len(np.zeros((4,))))

